"use client"

import { Loader2 } from "lucide-react"

import * as React from "react"
import { type FieldPath, useForm } from "react-hook-form"

import { Button } from "@/components/ui/button"
import { Form } from "@/components/ui/form"

import { TsFormConfirmationDialog } from "./ts-form-confirmation-dialog"
import { TsFormLayout } from "./ts-form-layout"
import { TsButton, TsConfirmation, TsErrors, TsFormProps } from "./types"
import {
  deepClone,
  deleteNestedKey,
  getButtonVariantClasses,
  getNestedValue,
  setNestedValue,
} from "./utils"

export function TsForm({
  layout,
  fields,
  values,
  buttons = [],
  errors,
  onAction,
  onFieldChange,
  readOnly = false,
  className,
  locale,
}: TsFormProps) {
  const formRef = React.useRef<HTMLFormElement>(null)

  // 1. Initialize Form
  const form = useForm<Record<string, unknown>>({
    defaultValues: values || {},
  })

  // Track field changes and emit onFieldChange without triggering parent re-render
  // Store previous values as deep object to match RHF structure
  const prevValuesRef = React.useRef<Record<string, unknown>>(values ? deepClone(values) : {})

  // Track paths that have manual errors from props to allow efficient cleanup
  const prevErrorPathsRef = React.useRef<Set<string>>(new Set())

  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/incompatible-library
    const subscription = form.watch((data, { name }) => {
      // name is undefined if the whole form is reset or changed, we only care about field-level changes
      if (name) {
        // Prototype pollution protection for incoming field names
        if (name === "__proto__" || name === "constructor" || name === "prototype") {
          return
        }

        const val = getNestedValue(data as Record<string, unknown>, name)
        onFieldChange?.(name, val, data as Record<string, unknown>)

        // Update ref to keep in sync with internal changes using deep set
        setNestedValue(prevValuesRef.current, name, val)
      }
    })
    return () => subscription.unsubscribe()
  }, [onFieldChange, form])

  // Update form values when props change surgically to preserve focus and avoid race conditions
  React.useEffect(() => {
    if (!values) return

    let hasChanged = false
    const activeElement = document.activeElement as HTMLElement
    // Find the field name by looking at the closest container with data-field attribute
    // This is more robust than activeElement.name for complex widgets
    const activeFieldName = activeElement?.closest("[data-field]")?.getAttribute("data-field")

    // Iterate over defined fields to check for changes (deep-path aware)
    Object.keys(fields).forEach((key) => {
      const path = key as FieldPath<Record<string, unknown>>

      // Skip synchronization ONLY for the field that currently has focus
      // to avoid cursor jumping. We allow updates for 'isDirty' fields if they are not active,
      // as the parent component's state should be the ultimate source of truth.
      if (key === activeFieldName) return

      const propValue = getNestedValue(values as Record<string, unknown>, key)
      const internalValue = getNestedValue(prevValuesRef.current, key)

      // Use basic comparison for primitives, assume object reference change means update
      if (propValue !== internalValue) {
        hasChanged = true
        form.setValue(path, propValue ?? null, {
          shouldDirty: false, // Maintain dirty state if it was already dirty
          shouldTouch: false,
          shouldValidate: false,
        })
        setNestedValue(prevValuesRef.current, key, propValue)
      }
    })

    if (hasChanged) {
      // Sync the whole ref as a fallback for any missed keys or deep structures
      prevValuesRef.current = deepClone(values)
    }
  }, [values, fields, form])

  // Handle external errors with cleanup and efficiency
  React.useEffect(() => {
    if (!errors) {
      if (prevErrorPathsRef.current.size > 0) {
        form.clearErrors()
        prevErrorPathsRef.current.clear()
      }
      return
    }

    const currentErrorPaths = new Set<string>()

    // Recursively discover and set error messages
    const syncErrors = (errs: TsErrors | string | unknown, currentPath: string = "") => {
      if (!errs || typeof errs !== "object") return

      // Direct string error message at path
      if (typeof errs === "string") {
        const path = currentPath as FieldPath<Record<string, unknown>>
        const currentInternal = form.getFieldState(path, form.formState).error
        if (currentInternal?.message !== errs) {
          form.setError(path, { type: "manual", message: errs })
        }
        currentErrorPaths.add(currentPath)
        return
      }

      // Handle arrays of errors
      if (Array.isArray(errs)) {
        errs.forEach((item, index) => {
          syncErrors(item, currentPath ? `${currentPath}.${index}` : `${index}`)
        })
        return
      }

      // Handle nested error objects or RHF-style { message: "..." } objects
      const errorObj = errs as Record<string, unknown>
      Object.keys(errorObj).forEach((key) => {
        const val = errorObj[key]
        const newPath = currentPath ? `${currentPath}.${key}` : key

        if (typeof val === "string") {
          const path = newPath as FieldPath<Record<string, unknown>>
          const currentInternal = form.getFieldState(path, form.formState).error
          if (currentInternal?.message !== val) {
            form.setError(path, { type: "manual", message: val })
          }
          currentErrorPaths.add(newPath)
        } else if (val && typeof val === "object") {
          const nestedVal = val as Record<string, unknown>
          if (typeof nestedVal.message === "string") {
            const path = newPath as FieldPath<Record<string, unknown>>
            const currentInternal = form.getFieldState(path, form.formState).error
            if (currentInternal?.message !== nestedVal.message) {
              form.setError(path, { type: "manual", message: nestedVal.message as string })
            }
            currentErrorPaths.add(newPath)
          } else {
            syncErrors(val, newPath)
          }
        }
      })
    }

    syncErrors(errors)

    // Flat key support for errors object root (e.g. { "items.0.name": "error" })
    const errorsDict = errors as Record<string, unknown>
    Object.keys(errorsDict).forEach((path) => {
      if (path.includes(".") && !currentErrorPaths.has(path)) {
        const message = getNestedValue(errorsDict, path)
        if (typeof message === "string") {
          const fieldPath = path as FieldPath<Record<string, unknown>>
          const currentInternal = form.getFieldState(fieldPath, form.formState).error
          if (currentInternal?.message !== message) {
            form.setError(fieldPath, { type: "manual", message })
          }
          currentErrorPaths.add(path)
        }
      }
    })

    // Efficient cleanup: Clear only those paths that were previously manual errors
    // but are no longer present in current error set.
    prevErrorPathsRef.current.forEach((path) => {
      if (!currentErrorPaths.has(path)) {
        form.clearErrors(path as FieldPath<Record<string, unknown>>)
      }
    })

    // Store current paths for next sync
    prevErrorPathsRef.current = currentErrorPaths
  }, [errors, fields, form])

  // Merge global properties into field definitions
  const mergedFields = React.useMemo(() => {
    return Object.fromEntries(
      Object.entries(fields).map(([key, field]) => {
        const merged = { ...field }
        if (readOnly) merged.readonly = true
        // Propagate global locale if not field-specific
        if (merged.type === "number" && !merged.locale && locale) {
          merged.locale = locale
        }
        return [key, merged]
      })
    )
  }, [fields, readOnly, locale])

  // Confirmation State
  const [confirmation, setConfirmation] = React.useState<{
    isOpen: boolean
    config: TsConfirmation | null
    pendingAction: string | null
    pendingData: Record<string, unknown> | null
  }>({ isOpen: false, config: null, pendingAction: null, pendingData: null })

  // Central submission logic - pass action explicitly
  const executeAction = React.useCallback(
    (action: string, data: Record<string, unknown>) => {
      const filteredData = deepClone(data)

      const keysToDelete = Object.keys(fields).filter((k) => fields[k]?.excludeFromSubmit)

      const arrayPaths: Record<string, number[]> = {}
      const simplePaths: string[] = []

      keysToDelete.forEach((path) => {
        // Support any array index in path (not just at the end), e.g. "users.0.tags.1"
        // We match all groups of digits that follow a dot
        const parts = path.split(".")
        let hasArrayIdx = false
        for (let i = parts.length - 1; i >= 0; i--) {
          if (/^\d+$/.test(parts[i])) {
            const parent = parts.slice(0, i).join(".")
            const index = parseInt(parts[i], 10)
            if (!arrayPaths[parent]) arrayPaths[parent] = []
            if (!arrayPaths[parent].includes(index)) arrayPaths[parent].push(index)
            hasArrayIdx = true
            // We break because deleting parent array element removes the child path
            break
          }
        }
        if (!hasArrayIdx) {
          simplePaths.push(path)
        }
      })

      // 1. Delete simple flat paths first
      simplePaths.forEach((p) => deleteNestedKey(filteredData, p))

      // 2. Delete array indices FROM END TO START for each array level
      // to maintain correct indices for remaining elements
      Object.keys(arrayPaths)
        .sort((a, b) => b.length - a.length)
        .forEach((parent) => {
          arrayPaths[parent]
            .sort((a, b) => b - a)
            .forEach((index) => {
              deleteNestedKey(filteredData, `${parent}.${index}`)
            })
        })

      onAction?.(action, filteredData)
    },
    [onAction, fields]
  )

  // Handle Enter/Escape actions - Scoped to form element
  React.useEffect(() => {
    const el = formRef.current
    if (!el) return

    const handleKeyAction = (e: Event) => {
      if (!(e instanceof CustomEvent)) return

      const detail = e.detail as {
        key: string
        action: string
        field: string
        value?: unknown
      }
      const { key, action, field, value } = detail

      if (value !== undefined) {
        const currentValue = form.getValues(field as FieldPath<Record<string, unknown>>)
        if (currentValue !== value) {
          form.setValue(field as FieldPath<Record<string, unknown>>, value, { shouldDirty: true })
        }
      }

      const currentValues = form.getValues() as Record<string, unknown>
      if (value !== undefined) {
        setNestedValue(currentValues, field, value)
      }

      if (key === "Enter") {
        if (action === "submit") {
          const submitBtn = buttons.find((b) => b.type === "submit") || buttons[0]
          if (submitBtn) {
            if (submitBtn.confirmation) {
              setConfirmation({
                isOpen: true,
                config: submitBtn.confirmation!,
                pendingAction: submitBtn.action,
                pendingData: currentValues,
              })
            } else {
              executeAction(submitBtn.action, currentValues)
            }
          }
        } else if (action === "focus:next") {
          const inputs = Array.from(
            el.querySelectorAll('input:not([type="hidden"]), textarea, select, button')
          ).filter((el) => {
            const htmlEl = el as HTMLElement & { disabled?: boolean; tabIndex: number }
            return !htmlEl.disabled && htmlEl.tabIndex !== -1 && htmlEl.offsetParent !== null
          })
          const currentIndex = inputs.indexOf(e.target as Element)
          if (currentIndex !== -1 && currentIndex < inputs.length - 1) {
            ;(inputs[currentIndex + 1] as HTMLElement).focus()
          }
        } else if (action) {
          executeAction(action, currentValues)
        }
      } else if (key === "Escape") {
        if (action === "cancel") {
          executeAction(action, currentValues)
        } else if (action) {
          executeAction(action, currentValues)
        }
      }
    }

    el.addEventListener("form-key-action", handleKeyAction)

    const handleFieldAction = (e: Event) => {
      if (!(e instanceof CustomEvent)) return
      const { action, data } = e.detail as { action: string; data: Record<string, unknown> }
      if (action) {
        executeAction(action, data || form.getValues())
      }
    }

    el.addEventListener("form-field-action", handleFieldAction)
    el.addEventListener("form-table-action", handleFieldAction)

    return () => {
      el.removeEventListener("form-key-action", handleKeyAction)
      el.removeEventListener("form-field-action", handleFieldAction)
      el.removeEventListener("form-table-action", handleFieldAction)
    }
  }, [form, buttons, executeAction])

  const handleButtonClick = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>, btn: TsButton) => {
      e.preventDefault()

      if (btn.type === "reset") {
        form.reset(values || {})
        prevValuesRef.current = values ? deepClone(values) : {}
        onAction?.(btn.action, form.getValues())
        return
      }

      const proceed = (data: Record<string, unknown>) => {
        if (btn.confirmation) {
          setConfirmation({
            isOpen: true,
            config: btn.confirmation,
            pendingAction: btn.action,
            pendingData: data,
          })
        } else {
          executeAction(btn.action, data)
        }
      }

      if (!btn.type || btn.type === "submit") {
        form.handleSubmit(proceed)(e)
      } else {
        proceed(form.getValues() as Record<string, unknown>)
      }
    },
    [form, values, executeAction, onAction]
  )

  const handleConfirmationAction = React.useCallback(
    (btnConfig: { action: string; confirm?: boolean }) => {
      if (btnConfig.confirm && confirmation.pendingAction && confirmation.pendingData) {
        executeAction(confirmation.pendingAction, confirmation.pendingData)
      }
      setConfirmation((prev) => ({ ...prev, isOpen: false }))
    },
    [confirmation.pendingAction, confirmation.pendingData, executeAction]
  )

  const renderButtons = React.useCallback(
    (btns: (TsButton | TsConfirmation["buttons"][0])[]) => {
      return btns.map((btn, idx) => {
        const { variant, className: customClass } = getButtonVariantClasses(btn.variant)
        const isConfirmBtn = "confirm" in btn

        return (
          <Button
            key={idx}
            type="button"
            variant={variant}
            className={customClass}
            onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
              if (isConfirmBtn) {
                handleConfirmationAction(btn as TsConfirmation["buttons"][0])
              } else {
                handleButtonClick(e, btn as TsButton)
              }
            }}
            disabled={!isConfirmBtn && form.formState.isSubmitting}
          >
            {!isConfirmBtn && form.formState.isSubmitting && (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            )}
            {btn.label}
          </Button>
        )
      })
    },
    [form.formState.isSubmitting, handleConfirmationAction, handleButtonClick]
  )

  return (
    <>
      <Form {...form}>
        <form ref={formRef} onSubmit={(e) => e.preventDefault()} className={className}>
          <TsFormLayout layout={layout} fields={mergedFields} />

          {buttons.length > 0 && !readOnly && (
            <div className="flex items-center justify-between gap-2 mt-6 pt-4 border-t w-full">
              <div className="flex flex-1 flex-row items-center justify-start gap-2">
                {renderButtons(buttons.filter((b) => b.position === "left"))}
              </div>
              <div className="flex flex-1 flex-row items-center justify-center gap-2">
                {renderButtons(buttons.filter((b) => b.position === "center"))}
              </div>
              <div className="flex flex-1 flex-row items-center justify-end gap-2">
                {renderButtons(buttons.filter((b) => !b.position || b.position === "right"))}
              </div>
            </div>
          )}
        </form>
      </Form>

      <TsFormConfirmationDialog
        isOpen={confirmation.isOpen}
        onOpenChange={(open) => setConfirmation((prev) => ({ ...prev, isOpen: open }))}
        config={confirmation.config}
        renderButtons={renderButtons}
      />
    </>
  )
}

"use client"

import * as React from "react"
import { useFormContext } from "react-hook-form"

import { Separator } from "@/components/ui/separator"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"

import { TsFormField } from "./ts-form-field"
import { TsFieldDef, TsLayout, TsRow } from "./types"

interface TsFormLayoutProps {
  layout: TsLayout
  fields: Record<string, TsFieldDef>
}

export function TsFormLayout({ layout, fields }: TsFormLayoutProps) {
  const {
    formState: { errors },
  } = useFormContext()

  if (layout.tabs && layout.tabs.length > 0) {
    return (
      <Tabs defaultValue={layout.tabs[0].label} className="w-full">
        <TabsList className="w-full justify-start overflow-x-auto scrollbar-hidden">
          {layout.tabs.map((tab, index) => {
            // Check if any field in this tab has an error (from state or definition)
            const hasError = tab.rows.some((row) =>
              row.some((item) => {
                if (!item.field) return false
                const fieldDef = fields[item.field]
                return errors[item.field] || (fieldDef && fieldDef.error)
              })
            )

            return (
              <TabsTrigger key={index} value={tab.label} className="relative">
                {tab.label}
                {hasError && (
                  <span className="absolute top-1 right-1 flex h-2 w-2 rounded-full bg-destructive" />
                )}
              </TabsTrigger>
            )
          })}
        </TabsList>
        {layout.tabs.map((tab, index) => (
          <TabsContent key={index} value={tab.label} className="space-y-4 pt-4">
            {renderRows(tab.rows, fields)}
          </TabsContent>
        ))}
      </Tabs>
    )
  }

  if (layout.rows) {
    return <div className="space-y-4">{renderRows(layout.rows, fields)}</div>
  }

  return null
}

function renderRows(rows: TsRow[], fields: Record<string, TsFieldDef>) {
  return rows.map((row, rowIndex) => {
    // Calculate grid template columns based on widths
    // Default width is 1fr if not specified
    const gridTemplateColumns = row.map((item) => item.width || "1fr").join(" ")

    return (
      <div key={rowIndex} className="grid gap-4 items-start" style={{ gridTemplateColumns }}>
        {row.map((item, colIndex) => {
          if (item.type === "empty") {
            return <div key={colIndex} />
          }

          if (item.type === "separator") {
            return (
              <div key={colIndex} className="col-span-full py-2">
                {item.label && (
                  <h4 className="text-sm font-medium text-muted-foreground mb-2">{item.label}</h4>
                )}
                <Separator />
              </div>
            )
          }

          const fieldDef = fields[item.field]
          if (!fieldDef) {
            return (
              <div key={colIndex} className="text-destructive text-sm">
                Field &apos;{item.field}&apos; not found
              </div>
            )
          }

          return <TsFormField key={item.field} name={item.field} fieldDef={fieldDef} />
        })}
      </div>
    )
  })
}

import { TsButtonVariant, TsFieldDef } from "./widget-types"

// Re-export commonly used types for easier imports
export * from "./widget-types"

// ─── Form definition ──────────────────────────────────────────────────────────

/**
 * Complete structure of a TsForm.
 * This object can be serialized/deserialized for dynamic form generation.
 */
export interface TsFormDef {
  /** Layout configuration (tabs or rows) */
  layout: TsLayout
  /** Dictionary of field definitions by key */
  fields: Record<string, TsFieldDef>
  /** Optional bottom buttons configuration */
  buttons?: TsButton[]
}

// ─── Form layout ──────────────────────────────────────────────────────────────

/**
 * Single item in a form row (field reference or special layout type).
 */
export interface TsRowItem {
  /** Key referencing fields object, or special type like 'empty' or 'separator' */
  field: string
  /** CSS grid width (e.g. '1fr', '200px', '50%') */
  width?: string
  /** Special layout type override */
  type?: "empty" | "separator"
  /** Label for 'separator' type */
  label?: string
  /** Horizontal alignment of the widget within its grid cell */
  align?: "left" | "center" | "right"
}

/**
 * Array of items forming one horizontal row in the layout grid.
 */
export type TsRow = TsRowItem[]

/**
 * Tab configuration for multi-page forms.
 */
export interface TsTab {
  /** Human-readable label for the tab */
  label: string
  /** Rows content within this tab */
  rows: TsRow[]
}

/**
 * Main layout definition for TsForm.
 * Supports either a multi-tab view or a flat list of rows.
 */
export interface TsLayout {
  /** Optional multi-tab configuration */
  tabs?: TsTab[]
  /** Flat row list for single-page forms (ignored if tabs is provided) */
  rows?: TsRow[]
}

// ─── Form buttons ─────────────────────────────────────────────────────────────

/**
 * Configuration for confirmation dialogs used by buttons.
 */
export interface TsConfirmation {
  /** Title text shown in the dialog header */
  title: string
  /** Detailed text message explaining the action and its consequences */
  text: string
  /** Buttons shown within the confirmation dialog */
  buttons: {
    /** Technical action name emitted if clicked */
    action: string
    /** Label text for the button */
    label: string
    /** Visual style variant */
    variant?: TsButtonVariant
    /** Whether this button triggers the 'confirm' action of the parent button */
    confirm?: boolean
    /** Visual position within the footer */
    position?: "left" | "center" | "right"
  }[]
}

/**
 * Configuration for a form action button.
 */
export interface TsButton {
  /** Technical action name emitted on click */
  action: string
  /** Human-readable label shown on the button */
  label: string
  /** Visual style variant from Shadcn/UI (e.g. 'default', 'outline', 'destructive') */
  variant?: TsButtonVariant
  /** HTML button type. 'submit' triggers form submission and internal validation check. */
  type?: "submit" | "button" | "reset"
  /** Lucide icon name (optional) */
  icon?: string
  /** Position in the bottom button bar */
  position?: "left" | "center" | "right"
  /** Optional confirmation dialog config before executing the action */
  confirmation?: TsConfirmation
  /** Whether the button is disabled */
  disabled?: boolean
  /** Whether the button is hidden */
  hidden?: boolean
}

// ─── Main Form Props ──────────────────────────────────────────────────────────

/**
 * Recursive structure for form validation errors.
 */
export type TsErrors = {
  [key: string]: string | TsErrors | TsErrors[] | Record<string, unknown> | undefined
}

/**
 * Props for the TsForm component.
 */
export interface TsFormProps {
  /** Layout definition (tabs or rows) */
  layout: TsLayout
  /** Dictionary of field definitions */
  fields: Record<string, TsFieldDef>
  /** Initial or current values of form fields (deep object support) */
  values?: Record<string, unknown>
  /** Bottom button bar configuration */
  buttons?: TsButton[]
  /** External validation errors from parent/backend */
  errors?: TsErrors
  /** Callback triggered when any button action is executed */
  onAction?: (action: string, data: Record<string, unknown>) => void
  /** Callback triggered on every field change (user interaction) */
  onFieldChange?: (name: string, value: unknown, data: Record<string, unknown>) => void
  /** Set the whole form to read-only mode */
  readOnly?: boolean
  /** Custom CSS classes for the container */
  className?: string
  /** Global locale for widgets (e.g. 'cs-CZ') */
  locale?: string
}

import React from "react"

/**
 * Default values for widgets to avoid magic numbers.
 */
export const DEFAULT_TEXTAREA_ROWS = 3

/**
 * Sanitizes a field name for use in HTML ID/aria-controls attributes.
 * Replaces any non-alphanumeric character with a hyphen for valid DOM IDs.
 */
export function sanitizeId(name: string): string {
  return name
    .replace(/[^a-zA-Z0-9]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
}

/**
 * Generates standard Tailwind classes for field states (error, readonly).
 * @param error Optional error message to trigger error styling.
 * @param readonly Whether the field is in read-only mode.
 */
export function getFieldClasses(error?: string, readonly?: boolean) {
  const hasError = !!error
  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = readonly ? "focus-visible:ring-0 focus-visible:border-input" : ""
  const readonlyPointerClass = readonly ? "cursor-default" : ""
  return { errorClass, readonlyClass, readonlyPointerClass }
}

/**
 * Safely gets a nested value from an object using a dot-notated path (e.g., "user.address.street" or "items.0.name").
 * @param obj The source object.
 * @param path Dot-notated path to the key.
 */
export function getNestedValue(obj: Record<string, unknown> | undefined, path: string): unknown {
  if (!obj || !path) return undefined

  // Prototype pollution protection
  if (path.includes("__proto__") || path.includes("constructor") || path.includes("prototype")) {
    return undefined
  }

  // 1. Try direct key access first (for flat structures or exact matches)
  if (Object.prototype.hasOwnProperty.call(obj, path)) {
    return obj[path]
  }
  // 2. Fallback to deep traversal
  const parts = path.split(".")
  let current: unknown = obj
  for (const part of parts) {
    if (current === null || typeof current !== "object") return undefined
    // Check if current part is an array index
    const isArrayIndex = /^\d+$/.test(part)
    current = isArrayIndex
      ? (current as unknown[])[parseInt(part, 10)]
      : (current as Record<string, unknown>)[part]
  }
  return current
}

/**
 * Safely sets a nested value in an object using a dot-notated path.
 * Mutates the original object. Creates missing objects/arrays along the path.
 * @param obj The target object.
 * @param path Dot-notated path.
 * @param value Value to set.
 */
export function setNestedValue(obj: Record<string, unknown>, path: string, value: unknown): void {
  if (!path) return

  const parts = path.split(".")
  const last = parts.pop()
  if (!last) return

  let current: unknown = obj
  for (const part of parts) {
    // Prototype pollution protection
    if (part === "__proto__" || part === "constructor" || part === "prototype") {
      return
    }

    const isArrayIndex = /^\d+$/.test(part)
    const key = isArrayIndex ? parseInt(part, 10) : part
    const currentObj = current as Record<string, unknown>

    if (
      currentObj[key] === undefined ||
      currentObj[key] === null ||
      typeof currentObj[key] !== "object"
    ) {
      // Peek ahead to see if the next part is an array index
      const nextPart = parts[parts.indexOf(part) + 1] || last
      currentObj[key] = /^\d+$/.test(nextPart) ? [] : {}
    }
    current = currentObj[key]
  }

  if (last === "__proto__" || last === "constructor" || last === "prototype") {
    return
  }

  const lastIsIndex = /^\d+$/.test(last)
  if (lastIsIndex && Array.isArray(current)) {
    ;(current as unknown[])[parseInt(last, 10)] = value
  } else {
    ;(current as Record<string, unknown>)[last!] = value
  }
}

/**
 * Safely deletes a nested key from an object using a dot-notated path (e.g., "user.address.street" or "items.0.name").
 * Mutates the original object.
 * @param obj The target object.
 * @param path Dot-notated path to the key.
 */
export function deleteNestedKey(obj: Record<string, unknown>, path: string): void {
  if (!path) return

  // Prototype pollution protection
  if (
    path.includes("__proto__") ||
    path.split(".").some((p) => p === "constructor" || p === "prototype")
  ) {
    return
  }

  const parts = path.split(".")
  const last = parts.pop()
  if (!last) return

  let current: unknown = obj
  for (const part of parts) {
    const isArrayIndex = /^\d+$/.test(part)
    const key = isArrayIndex ? parseInt(part, 10) : part
    const currentObj = current as Record<string, unknown>
    const next = currentObj[key]

    if (next && typeof next === "object") {
      current = next
    } else {
      return
    }
  }

  const lastIsIndex = /^\d+$/.test(last)
  if (lastIsIndex && Array.isArray(current)) {
    const index = parseInt(last, 10)
    if (index >= 0 && index < (current as unknown[]).length) {
      ;(current as unknown[]).splice(index, 1)
    }
  } else if (
    current &&
    typeof current === "object" &&
    Object.prototype.hasOwnProperty.call(current, last)
  ) {
    delete (current as Record<string, unknown>)[last]
  }
}

/**
 * A safer alternative to structuredClone for form data.
 * Handles primitives, plain objects, arrays, Dates and Files.
 *
 * NOTE: Files/Blobs are kept by reference (not cloned) because they are immutable
 * and structuredClone is not reliably available for Files in all target environments.
 */
export function deepClone<T>(val: T): T {
  // Primitives and null are returned as-is
  if (val === null || typeof val !== "object") return val

  // Dates are cloned to a new instance.
  // Cast is necessary because T is a generic type and TS cannot guarantee it matches Date.
  if (val instanceof Date) return new Date(val.getTime()) as unknown as T

  // Files and Blobs are considered immutable for our purposes and kept by reference.
  // Cast is necessary because T is generic.
  if (val instanceof File || val instanceof Blob) return val as unknown as T

  // Recursively clone arrays.
  // Cast is necessary because map returns a new array that TS doesn't automatically map back to T.
  if (Array.isArray(val)) {
    return val.map((item) => deepClone(item)) as unknown as T
  }

  // Recursively clone plain objects.
  const clonedObj: Record<string, unknown> = {}
  const sourceObj = val as Record<string, unknown>
  for (const key in sourceObj) {
    if (Object.prototype.hasOwnProperty.call(sourceObj, key)) {
      clonedObj[key] = deepClone(sourceObj[key])
    }
  }
  // Cast is necessary to convert our cloned record back to the original generic type T.
  return clonedObj as unknown as T
}

export function handleFieldKeyDown(
  e: React.KeyboardEvent,
  name: string,
  enterAction?: string,
  escapeAction?: string,
  onClear?: () => void,
  commitValue?: unknown
) {
  if (e.key === "Enter") {
    // For Textarea we ignore Enter (want new line),
    // unless pressed with Ctrl/Meta (then we perform action)
    const isTextarea = (e.currentTarget as HTMLElement).tagName === "TEXTAREA"
    if (isTextarea && !e.ctrlKey && !e.metaKey) return

    if (enterAction) {
      e.preventDefault()
      e.stopPropagation()
      const event = new CustomEvent("form-key-action", {
        detail: {
          key: "Enter",
          action: enterAction,
          field: name,
          value: commitValue, // Pass current value to avoid race conditions
        },
        bubbles: true,
      })
      ;(e.currentTarget as HTMLElement).dispatchEvent(event)
    }
  } else if (e.key === "Escape") {
    e.preventDefault()
    e.stopPropagation()
    if (!escapeAction || escapeAction === "clear") {
      onClear?.()
    }
    if (escapeAction) {
      const event = new CustomEvent("form-key-action", {
        detail: { key: "Escape", action: escapeAction, field: name },
        bubbles: true,
      })
      ;(e.currentTarget as HTMLElement).dispatchEvent(event)
    }
  }
}

/**
 * Safely evaluates a simple mathematical expression (addition, subtraction, multiplication, division).
 * Supports both dot and comma as decimal separators.
 * Implementation avoids 'eval' or 'new Function' for security.
 */
export function evaluateMath(val: string): number | undefined {
  if (!val || val.trim() === "") return undefined

  // Normalize: remove spaces, replace all commas with dots
  const expression = val.replace(/\s/g, "").replace(/,/g, ".")

  // Only allow numbers and basic math operators
  if (!/^[0-9.+\-*/^()]+$/.test(expression)) return undefined

  try {
    const tokens = expression.match(/[0-9.]+|[+\-*/^()]/g) || []
    if (tokens.length === 0) return undefined

    const ops = {
      "+": (a: number, b: number) => a + b,
      "-": (a: number, b: number) => a - b,
      "*": (a: number, b: number) => a * b,
      "/": (a: number, b: number) => a / b,
      "^": (a: number, b: number) => Math.pow(a, b),
    }

    const precedence: Record<string, number> = { "+": 1, "-": 1, "*": 2, "/": 2, "^": 3 }
    const values: number[] = []
    const operators: string[] = []

    const applyOp = (): boolean => {
      const op = operators.pop()
      if (!op || values.length < 2) return false
      const b = values.pop()!
      const a = values.pop()!
      const operation = ops[op as keyof typeof ops]
      if (!operation) return false
      values.push(operation(a, b))
      return true
    }

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i]

      // Handle unary minus and plus: if '-' or '+' is the first token or follows an opening parenthesis
      if ((token === "-" || token === "+") && (i === 0 || tokens[i - 1] === "(")) {
        if (token === "-") {
          values.push(0) // Treat -X as 0 - X
          operators.push("-")
        }
        // Unary '+' is just ignored as it doesn't change the value (treat +X as X)
        continue
      }

      if (!isNaN(Number(token))) {
        values.push(Number(token))
      } else if (token === "(") {
        operators.push(token)
      } else if (token === ")") {
        while (operators.length && operators[operators.length - 1] !== "(") {
          if (!applyOp()) return undefined
        }
        operators.pop()
      } else {
        while (
          operators.length &&
          operators[operators.length - 1] !== "(" &&
          precedence[operators[operators.length - 1]] >= precedence[token]
        ) {
          if (!applyOp()) return undefined
        }
        operators.push(token)
      }
    }

    while (operators.length) {
      if (!applyOp()) return undefined
    }

    const rawResult = values[0]
    // Fix floating point precision (e.g., 0.1 + 0.2) by rounding to 12 decimal places
    const result = typeof rawResult === "number" ? Math.round(rawResult * 1e12) / 1e12 : undefined

    return typeof result === "number" && isFinite(result) && values.length === 1
      ? result
      : undefined
  } catch {
    return undefined
  }
}

/**
 * Parses a string value into a number, supporting localized formats and basic math expressions.
 */
export function parseNumericValue(val: string): number | undefined {
  if (!val || val.trim() === "") return undefined

  // Try direct float parsing first (normalized)
  const normalized = val.replace(/\s/g, "").replace(",", ".")
  const num = parseFloat(normalized)

  // If the whole string is a valid float, return it
  if (!isNaN(num) && String(num) === normalized) {
    return num
  }

  // Otherwise, try evaluating it as a math expression
  return evaluateMath(val)
}

/**
 * Formats a number for display according to locale and rounding settings.
 */
export function formatNumericValue(
  val: number | undefined,
  roundTo?: number,
  locale?: string
): string {
  if (val === undefined || val === null) return ""

  const options: Intl.NumberFormatOptions = {
    minimumFractionDigits: roundTo !== undefined ? roundTo : 0,
    maximumFractionDigits: roundTo !== undefined ? roundTo : 2,
  }

  return new Intl.NumberFormat(locale || undefined, options).format(val)
}

/**
 * Maps custom TsButtonVariant to Shadcn button variants and additional CSS classes.
 */
export function getButtonVariantClasses(variant?: string): {
  variant: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link"
  className: string
} {
  let shadcnVariant: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link" =
    "default"
  let className = ""

  if (!variant) return { variant: shadcnVariant, className }

  if (variant === "primary") {
    className = "bg-blue-600 text-white hover:bg-blue-700 border-none"
  } else if (variant === "success") {
    className = "bg-green-600 text-white hover:bg-green-700 border-none"
  } else if (variant === "warning") {
    className = "bg-amber-500 text-white hover:bg-amber-600 border-none"
  } else if (variant === "danger" || variant === "destructive") {
    shadcnVariant = "destructive"
  } else if (["default", "outline", "secondary", "ghost", "link"].includes(variant)) {
    shadcnVariant = variant as typeof shadcnVariant
  }

  return { variant: shadcnVariant, className }
}

"use client"

import * as React from "react"
import { ControllerRenderProps, FieldValues } from "react-hook-form"

import { Button } from "@/components/ui/button"

import { cn } from "@/lib/utils"

import { TsButtonGroupField, TsFieldOptions } from "../types"
import { getFieldClasses } from "../utils"

export interface TsButtonGroupWidgetProps {
  field: ControllerRenderProps<FieldValues, string>
  def: TsButtonGroupField
  error?: string
}

export const ButtonGroupWidget = React.forwardRef<HTMLDivElement, TsButtonGroupWidgetProps>(
  ({ field, def, error, ...props }, ref) => {
    const { readonlyPointerClass } = getFieldClasses(error, def.readonly)
    const hasError = !!error

    if (def.variant === "process") {
      return <ProcessButtonGroup field={field} def={def} />
    }

    return (
      <div
        className={cn(
          "flex",
          def.disabled && "opacity-50 pointer-events-none",
          readonlyPointerClass
        )}
        {...props}
        ref={ref}
      >
        {(def.options || []).map((opt: TsFieldOptions | string, index, arr) => {
          let value: string
          let label: string
          let optVariant: string | undefined
          let isDisabled = false

          if (typeof opt === "string") {
            const parts = opt.split("/")
            value = parts[0]
            isDisabled = parts[1] === "false"
            optVariant = parts[2] || undefined
            label = parts[3] || parts[0]
          } else {
            value = String(opt.value)
            label = opt.label
            optVariant = opt.variant
            isDisabled = !!opt.disabled
          }

          const isActive = field.value === value
          const isFirst = index === 0
          const isLast = index === arr.length - 1
          const rawVariant = isActive
            ? optVariant || "default"
            : optVariant
              ? optVariant
              : "outline"

          let variant: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link" =
            "outline"
          if (rawVariant === "destructive" || rawVariant === "danger") variant = "destructive"
          else if (rawVariant === "secondary") variant = "secondary"
          else if (rawVariant === "ghost") variant = "ghost"
          else if (rawVariant === "link") variant = "link"
          else if (rawVariant === "outline") variant = "outline"
          else variant = "default"

          return (
            <Button
              key={value}
              type="button"
              variant={variant}
              disabled={def.disabled || isDisabled}
              className={cn(
                !isFirst && "-ml-px",
                isFirst && !isLast && "rounded-r-none",
                isLast && !isFirst && "rounded-l-none",
                !isFirst && !isLast && "rounded-none",
                isActive && "relative z-10",
                hasError && "border-destructive text-destructive"
              )}
              onClick={() => {
                if (!def.disabled && !def.readonly && !isDisabled) field.onChange(value)
              }}
              aria-invalid={hasError}
            >
              {label}
            </Button>
          )
        })}
      </div>
    )
  }
)
ButtonGroupWidget.displayName = "ButtonGroupWidget"

// ─── ProcessButtonGroup ───────────────────────────────────────────────────────

function ProcessButtonGroup({
  field,
  def,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsButtonGroupField
}) {
  const options = (def.options || []).map((opt: TsFieldOptions | string) => {
    if (typeof opt === "string") {
      const parts = opt.split("/")
      const value = parts[0]
      const isEnabled = parts[1] !== "false"
      const variant = parts[2] || undefined
      const label = parts[3] || parts[0]
      return { value, label, variant, disabled: !isEnabled }
    }
    return {
      value: String(opt.value),
      label: opt.label,
      variant: opt.variant,
      disabled: opt.disabled,
    }
  })

  const ARROW = 12

  const getClipPath = (): string => {
    return `polygon(0 0, calc(100% - ${ARROW}px) 0, 100% 50%, calc(100% - ${ARROW}px) 100%, 0 100%, ${ARROW}px 50%)`
  }

  const getBgClass = (variant: string | undefined, isActive: boolean): string => {
    if (isActive) {
      switch (variant) {
        case "success":
          return "bg-green-600 text-white dark:bg-green-500 hover:bg-green-700 dark:hover:bg-green-400"
        case "destructive":
        case "danger":
          return "bg-destructive text-destructive-foreground hover:bg-destructive/90"
        case "warning":
          return "bg-amber-500 text-white hover:bg-amber-600"
        case "secondary":
          return "bg-secondary text-secondary-foreground hover:bg-secondary/80"
        default:
          return "bg-primary text-primary-foreground hover:bg-primary/90"
      }
    } else {
      switch (variant) {
        case "success":
          return "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 hover:bg-green-200"
        case "destructive":
        case "danger":
          return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 hover:bg-red-200"
        case "warning":
          return "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 hover:bg-amber-200"
        case "secondary":
          return "bg-secondary/30 text-secondary-foreground hover:bg-secondary/50"
        default:
          return "bg-muted text-muted-foreground hover:bg-accent hover:text-accent-foreground"
      }
    }
  }

  return (
    <div className="flex items-stretch">
      {options.map((opt, index) => {
        const isActive = field.value === opt.value
        const clipPath = getClipPath()
        const isInteractive = !def.disabled && !def.readonly

        return (
          <div
            key={opt.value}
            className="relative h-10"
            style={{
              marginLeft: index > 0 ? `${-ARROW}px` : undefined,
              zIndex: isActive ? 10 : options.length - index,
            }}
          >
            <button
              type="button"
              disabled={def.disabled || opt.disabled}
              onClick={() => {
                if (isInteractive && !opt.disabled) field.onChange(opt.value)
              }}
              className={cn(
                "relative h-full px-10 text-sm font-medium transition-colors",
                getBgClass(opt.variant, isActive),
                (def.disabled || opt.disabled) && "opacity-50 cursor-not-allowed",
                def.readonly && "pointer-events-none"
              )}
              style={{ clipPath }}
            >
              {opt.label}
            </button>
          </div>
        )
      })}
    </div>
  )
}

