export const TextWidget = React.forwardRef<HTMLInputElement, TsTextWidgetProps>(
  ({ field, def, name, error, ...props }, ref) => {
    const safeId = sanitizeId(name)
    const [showPassword, setShowPassword] = React.useState(false)
    const [internalValue, setInternalValue] = React.useState((field.value as string) ?? "")
    const { errorClass, readonlyClass, readonlyPointerClass } = getFieldClasses(error, def.readonly)

    // Sync internal value with external changes only when not focused or value changed significantly
    React.useEffect(() => {
      const newVal = (field.value as string) ?? ""
      if (newVal !== internalValue) {
        setInternalValue(newVal)
      }
    }, [field.value, internalValue])

    const isPassword = def.type === "password"
    const inputType = isPassword ? (showPassword ? "text" : "password") : def.type

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value
      setInternalValue(val)
      field.onChange(val)
    }

    return (
      <div className="relative">
        <Input
          id={safeId}
          type={inputType}
          placeholder={def.placeholder}
          {...field}
          {...props}
          ref={ref || field.ref}
          value={internalValue}
          onChange={handleChange}
          onKeyDown={(e) =>
            handleFieldKeyDown(
              e,
              name,
              def.enterAction,
              def.escapeAction,
              () => {
                setInternalValue("")
                field.onChange("")
              },
              internalValue
            )
          }
          disabled={def.disabled}
          readOnly={def.readonly}
          tabIndex={def.readonly ? -1 : undefined}
          aria-invalid={!!error}
          onFocus={(e) => {
            if (def.selectAllOnFocus && !def.readonly) {
              const el = e.currentTarget
              setTimeout(() => el.select(), 0)
            }
          }}
          onClick={(e) => {
            if (
              def.selectAllOnFocus &&
              !def.readonly &&
              document.activeElement !== e.currentTarget
            ) {
              e.currentTarget.select()
            }
          }}
          className={cn(errorClass, readonlyClass, readonlyPointerClass, isPassword && "pr-10")}
        />
        {isPassword && !def.readonly && !def.disabled && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="absolute right-0 top-0 h-full w-10 hover:bg-transparent"
            onClick={() => setShowPassword(!showPassword)}
          >
            {showPassword ? (
              <EyeOff className="h-4 w-4 text-muted-foreground" />
            ) : (
              <Eye className="h-4 w-4 text-muted-foreground" />
            )}
            <span className="sr-only">{showPassword ? "Hide password" : "Show password"}</span>
          </Button>
        )}
      </div>
    )
  }
)
TextWidget.displayName = "TextWidget"

import * as React from "react"
import { ControllerRenderProps, FieldValues } from "react-hook-form"

import { Textarea } from "@/components/ui/textarea"

import { cn } from "@/lib/utils"

import { TsTextareaField } from "../types"
import { DEFAULT_TEXTAREA_ROWS, getFieldClasses, handleFieldKeyDown, sanitizeId } from "../utils"

export interface TsTextareaWidgetProps {
  field: ControllerRenderProps<FieldValues, string>
  def: TsTextareaField
  name: string
  error?: string
}

export const TextareaWidget = React.forwardRef<HTMLTextAreaElement, TsTextareaWidgetProps>(
  ({ field, def, name, error, ...props }, ref) => {
    const safeId = sanitizeId(name)
    const { errorClass, readonlyClass } = getFieldClasses(error, def.readonly)

    return (
      <Textarea
        id={safeId}
        placeholder={def.placeholder}
        {...field}
        {...props}
        ref={ref || field.ref}
        value={(field.value as string) ?? ""}
        rows={def.rows || DEFAULT_TEXTAREA_ROWS}
        onKeyDown={(e) =>
          handleFieldKeyDown(e, name, def.enterAction, def.escapeAction, () => field.onChange(""))
        }
        disabled={def.disabled}
        readOnly={def.readonly}
        tabIndex={def.readonly ? -1 : undefined}
        aria-invalid={!!error}
        onFocus={(e) => {
          if (def.selectAllOnFocus && !def.readonly) {
            const el = e.currentTarget
            setTimeout(() => el.select(), 0)
          }
        }}
        onClick={(e) => {
          if (def.selectAllOnFocus && !def.readonly && document.activeElement !== e.currentTarget) {
            e.currentTarget.select()
          }
        }}
        className={cn(errorClass, readonlyClass)}
      />
    )
  }
)
TextareaWidget.displayName = "TextareaWidget"
